'use strict';

const fs = require('fs');
const path = require('path');

const README = path.join(__dirname, 'README.md');
const INDEX = path.join(__dirname, 'INDEX.md');

const HEADING = /^#{1,6}\s+\S/;

function main() {
  const source = fs.readFileSync(README, 'utf8');
  const headings = source
    .split(/\r?\n/)
    .filter((line) => HEADING.test(line.trim()))
    .map((line) => line.trim());

  fs.writeFileSync(INDEX, headings.join('\n') + (headings.length ? '\n' : ''), 'utf8');

  console.log(`Wrote ${headings.length} heading(s) to ${path.basename(INDEX)}`);
}

main();

